// Super Admin initialization and management

import { auth } from '../providers/index.js';
import { config } from '../config.js';

const SUPER_ADMIN_STORAGE_KEY = 'bmms_super_admin_initialized';

/**
 * Check if super admin account exists in Appwrite
 */
export async function checkSuperAdminExists() {
    const superEmail = getSuperAdminEmail();
    if (!superEmail) return false;

    try {
        // Try to sign in with super admin credentials
        const { data, error } = await auth.signIn(superEmail, config.SUPER_ADMIN_PASSWORD);
        if (data?.user) {
            return true;
        }
        return false;
    } catch (error) {
        return false;
    }
}

/**
 * Create super admin account in Appwrite
 */
export async function initializeSuperAdmin() {
    const superUsername = config.SUPER_ADMIN_USERNAME;
    const superPassword = config.SUPER_ADMIN_PASSWORD;
    const superEmail = getSuperAdminEmail();

    if (!superUsername || !superPassword) {
        throw new Error('Super admin credentials not configured in environment');
    }

    try {
        // Create Appwrite auth account
        const { data: authData, error: authError } = await auth.signUp(
            superEmail,
            superPassword,
            { username: superUsername }
        );

        if (authError) {
            // If user already exists, that's ok
            if (authError.message?.includes('already')) {
                console.log('Super admin account already exists');
                return { success: true, alreadyExists: true };
            }
            throw authError;
        }

        // Mark as initialized
        localStorage.setItem(SUPER_ADMIN_STORAGE_KEY, 'true');

        return { success: true, user: authData.user };
    } catch (error) {
        console.error('Failed to initialize super admin:', error);
        throw error;
    }
}

/**
 * Login as super admin using Appwrite auth
 */
export async function loginSuperAdmin() {
    const superEmail = getSuperAdminEmail();
    const superPassword = config.SUPER_ADMIN_PASSWORD;

    if (!superEmail || !superPassword) {
        throw new Error('Super admin credentials not configured');
    }

    try {
        const { data, error } = await auth.signIn(superEmail, superPassword);

        if (error) {
            // If password doesn't match, might have been changed in .env
            if (error.message?.includes('Invalid credentials') || error.code === 401) {
                throw new Error('Super admin password mismatch. Please update password in Appwrite Console or delete the account to reinitialize.');
            }
            throw error;
        }

        return { success: true, user: data.user };
    } catch (error) {
        console.error('Super admin login failed:', error);
        throw error;
    }
}

/**
 * Check if we should auto-initialize super admin
 */
export function shouldInitializeSuperAdmin() {
    return !localStorage.getItem(SUPER_ADMIN_STORAGE_KEY);
}

/**
 * Get super admin email from username
 */
function getSuperAdminEmail() {
    const username = config.SUPER_ADMIN_USERNAME;
    if (!username) return null;

    // Use a special domain for super admin
    return `${username}@bmms.superadmin.local`;
}

/**
 * Verify if credentials match super admin
 */
export function verifySuperAdminCredentials(username, password) {
    return (
        username === config.SUPER_ADMIN_USERNAME &&
        password === config.SUPER_ADMIN_PASSWORD
    );
}
