<script>
  import { onDestroy } from 'svelte';
  import { uiStore } from '../stores/index.js';

  $: notification = $uiStore.notification;

  let timer = null;
  let isPaused = false;
  let remainingTime = 0;
  let startTime = 0;

  // 当 notification 变化时重置计时器
  $: if (notification) {
    startTimer(notification.duration || 5000);
  } else {
    clearTimer();
  }

  function startTimer(duration) {
    clearTimer();
    remainingTime = duration;
    startTime = Date.now();
    timer = setTimeout(() => {
      uiStore.hideNotification();
    }, remainingTime);
  }

  function pauseTimer() {
    if (timer && !isPaused) {
      isPaused = true;
      clearTimeout(timer);
      timer = null;
      // 计算剩余时间
      const elapsed = Date.now() - startTime;
      remainingTime = Math.max(0, remainingTime - elapsed);
    }
  }

  function resumeTimer() {
    if (isPaused && remainingTime > 0) {
      isPaused = false;
      startTime = Date.now();
      timer = setTimeout(() => {
        uiStore.hideNotification();
      }, remainingTime);
    }
  }

  function clearTimer() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
    isPaused = false;
    remainingTime = 0;
  }

  function handleClose() {
    uiStore.hideNotification();
  }

  function handleMouseEnter() {
    pauseTimer();
  }

  function handleMouseLeave() {
    resumeTimer();
  }

  onDestroy(() => {
    clearTimer();
  });
</script>

{#if notification}
  <div 
    class="notification-container"
    on:mouseenter={handleMouseEnter}
    on:mouseleave={handleMouseLeave}
    role="alert"
  >
    <div class="notification {notification.type}">
      <span class="notification-icon">
        {#if notification.type === 'success'}
          ✓
        {:else if notification.type === 'error'}
          ✕
        {:else if notification.type === 'warning'}
          ⚠
        {:else}
          ℹ
        {/if}
      </span>
      <div class="notification-content">
        {#each notification.message.split('\n') as line}
          <div class="notification-line">{line}</div>
        {/each}
      </div>
      <button class="notification-close" on:click={handleClose} aria-label="关闭">
        ×
      </button>
    </div>
  </div>
{/if}

